-- Milestone 3b: platform (Super Admin) identity and break-glass support access (ADR-0003 section 4, section 8).
-- Part 1 is generated by Prisma from schema.prisma. Part 2 (security) is hand-written.
-- Runs as kenisha_migrator with search_path = kenisha.
-- Wrapped in one transaction: Prisma does not do this itself, and a partial migration
-- would leave tables without their RLS policies.

BEGIN;

-- ===========================================================================
-- Part 1: tables (generated)
-- ===========================================================================

-- CreateEnum
CREATE TYPE "PlatformUserStatus" AS ENUM ('ACTIVE', 'DISABLED');

-- CreateEnum
CREATE TYPE "SupportAccessStatus" AS ENUM ('REQUESTED', 'APPROVED', 'REJECTED', 'REVOKED');

-- CreateTable
CREATE TABLE "platform_users" (
    "id" UUID NOT NULL DEFAULT uuidv7(),
    "email" VARCHAR(254) NOT NULL,
    "display_name" VARCHAR(200) NOT NULL,
    "password_hash" VARCHAR(255) NOT NULL,
    "totp_secret_encrypted" VARCHAR(255) NOT NULL,
    "totp_last_used_step" BIGINT,
    "failed_attempts" INTEGER NOT NULL DEFAULT 0,
    "locked_until" TIMESTAMPTZ(3),
    "status" "PlatformUserStatus" NOT NULL DEFAULT 'ACTIVE',
    "created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ(3) NOT NULL,

    CONSTRAINT "platform_users_pkey" PRIMARY KEY ("id")
);

-- CreateTable
CREATE TABLE "platform_sessions" (
    "id" UUID NOT NULL DEFAULT uuidv7(),
    "platform_user_id" UUID NOT NULL,
    "refresh_token_hash" CHAR(64) NOT NULL,
    "refresh_generation" INTEGER NOT NULL DEFAULT 0,
    "last_refreshed_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "idle_timeout_secs" INTEGER NOT NULL,
    "expires_at" TIMESTAMPTZ(3) NOT NULL,
    "revoked_at" TIMESTAMPTZ(3),
    "revoke_reason" VARCHAR(50),
    "ip" VARCHAR(45),
    "user_agent" VARCHAR(300),
    "created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "platform_sessions_pkey" PRIMARY KEY ("id")
);

-- CreateTable
CREATE TABLE "platform_audit_events" (
    "id" UUID NOT NULL DEFAULT uuidv7(),
    "actor_platform_user_id" UUID,
    "tenant_id" UUID,
    "action" VARCHAR(64) NOT NULL,
    "outcome" "AuditOutcome" NOT NULL,
    "target_type" VARCHAR(50),
    "target_id" UUID,
    "ip" VARCHAR(45),
    "user_agent" VARCHAR(300),
    "metadata" JSONB,
    "created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "platform_audit_events_pkey" PRIMARY KEY ("id")
);

-- CreateTable
CREATE TABLE "support_access_requests" (
    "id" UUID NOT NULL DEFAULT uuidv7(),
    "tenant_id" UUID NOT NULL,
    "requested_by_id" UUID NOT NULL,
    "requester_name" VARCHAR(200) NOT NULL,
    "reason" VARCHAR(1000) NOT NULL,
    "requested_minutes" INTEGER NOT NULL,
    "status" "SupportAccessStatus" NOT NULL DEFAULT 'REQUESTED',
    "decided_by_user_id" UUID,
    "decided_at" TIMESTAMPTZ(3),
    "approved_until" TIMESTAMPTZ(3),
    "created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ(3) NOT NULL,

    CONSTRAINT "support_access_requests_pkey" PRIMARY KEY ("id")
);

-- CreateIndex
CREATE UNIQUE INDEX "platform_users_email_key" ON "platform_users"("email");

-- CreateIndex
CREATE INDEX "platform_sessions_platform_user_id_idx" ON "platform_sessions"("platform_user_id");

-- CreateIndex
CREATE INDEX "platform_audit_events_created_at_idx" ON "platform_audit_events"("created_at");

-- CreateIndex
CREATE INDEX "support_access_requests_tenant_id_created_at_idx" ON "support_access_requests"("tenant_id", "created_at");

-- CreateIndex
CREATE INDEX "support_access_requests_requested_by_id_idx" ON "support_access_requests"("requested_by_id");

-- AddForeignKey
ALTER TABLE "platform_sessions" ADD CONSTRAINT "platform_sessions_platform_user_id_fkey" FOREIGN KEY ("platform_user_id") REFERENCES "platform_users"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "support_access_requests" ADD CONSTRAINT "support_access_requests_tenant_id_fkey" FOREIGN KEY ("tenant_id") REFERENCES "tenants"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "support_access_requests" ADD CONSTRAINT "support_access_requests_requested_by_id_fkey" FOREIGN KEY ("requested_by_id") REFERENCES "platform_users"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "support_access_requests" ADD CONSTRAINT "support_access_requests_tenant_id_decided_by_user_id_fkey" FOREIGN KEY ("tenant_id", "decided_by_user_id") REFERENCES "users"("tenant_id", "id") ON DELETE RESTRICT ON UPDATE CASCADE;


-- ===========================================================================
-- Part 2: security (hand-written - review carefully)
--
-- * Platform tables: only kenisha_platform, which still has NO access to tenant data.
-- * support_access_requests: the platform may only CREATE requests (in status REQUESTED);
--   only the hospital (kenisha_app, in its own tenant context) may approve, reject or
--   revoke them. A database trigger allows only REQUESTED -> APPROVED/REJECTED and
--   APPROVED -> REVOKED, and approval can never exceed the requested duration.
-- ===========================================================================

-- Data checks ------------------------------------------------------------------
ALTER TABLE "platform_users"
  ADD CONSTRAINT "platform_users_email_lowercase" CHECK ("email" = lower("email"));
ALTER TABLE "platform_sessions"
  ADD CONSTRAINT "platform_sessions_refresh_hash_hex" CHECK ("refresh_token_hash" ~ '^[0-9a-f]{64}$');
ALTER TABLE "platform_audit_events"
  ADD CONSTRAINT "platform_audit_events_action_format" CHECK ("action" ~ '^[A-Z][A-Z0-9_]{2,63}$');
ALTER TABLE "support_access_requests"
  ADD CONSTRAINT "support_access_duration" CHECK ("requested_minutes" BETWEEN 15 AND 240),
  ADD CONSTRAINT "support_access_reason_length" CHECK (char_length("reason") >= 20),
  ADD CONSTRAINT "support_access_decision_complete" CHECK (
    ("status" = 'REQUESTED' AND "decided_at" IS NULL AND "decided_by_user_id" IS NULL AND "approved_until" IS NULL)
    OR ("status" <> 'REQUESTED' AND "decided_at" IS NOT NULL AND "decided_by_user_id" IS NOT NULL)
  ),
  ADD CONSTRAINT "support_access_approval_window" CHECK (
    ("status" NOT IN ('APPROVED', 'REVOKED') AND "approved_until" IS NULL)
    OR ("status" IN ('APPROVED', 'REVOKED') AND "approved_until" IS NOT NULL
        AND "approved_until" <= "decided_at" + make_interval(mins => "requested_minutes"))
  );

-- Allowed status transitions ------------------------------------------------------
CREATE FUNCTION "support_access_requests_guard"() RETURNS trigger
  LANGUAGE plpgsql
  SET search_path = pg_catalog, pg_temp
  AS $$
  BEGIN
    IF NOT (
      (OLD.status = 'REQUESTED' AND NEW.status IN ('APPROVED', 'REJECTED'))
      OR (OLD.status = 'APPROVED' AND NEW.status = 'REVOKED')
    ) THEN
      RAISE EXCEPTION 'support access request cannot move from % to %', OLD.status, NEW.status
        USING ERRCODE = 'check_violation';
    END IF;
    -- Revoking ends access now; it never extends it.
    IF NEW.status = 'REVOKED' THEN
      NEW.approved_until := LEAST(OLD.approved_until, now());
      NEW.decided_by_user_id := COALESCE(NEW.decided_by_user_id, OLD.decided_by_user_id);
    END IF;
    RETURN NEW;
  END
  $$;

CREATE TRIGGER "support_access_requests_guard"
  BEFORE UPDATE ON "support_access_requests"
  FOR EACH ROW EXECUTE FUNCTION "support_access_requests_guard"();

-- platform_users / platform_sessions / platform_audit_events -------------------------
ALTER TABLE "platform_users" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "platform_users" FORCE ROW LEVEL SECURITY;
GRANT SELECT, INSERT ON "platform_users" TO kenisha_platform;
GRANT UPDATE ("display_name", "password_hash", "totp_secret_encrypted", "totp_last_used_step",
              "failed_attempts", "locked_until", "status", "updated_at") ON "platform_users" TO kenisha_platform;
CREATE POLICY "platform_users_platform_all" ON "platform_users" TO kenisha_platform
  USING (true) WITH CHECK (true);

ALTER TABLE "platform_sessions" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "platform_sessions" FORCE ROW LEVEL SECURITY;
GRANT SELECT, INSERT ON "platform_sessions" TO kenisha_platform;
GRANT UPDATE ("refresh_token_hash", "refresh_generation", "last_refreshed_at", "expires_at",
              "revoked_at", "revoke_reason") ON "platform_sessions" TO kenisha_platform;
CREATE POLICY "platform_sessions_platform_all" ON "platform_sessions" TO kenisha_platform
  USING (true) WITH CHECK (true);

ALTER TABLE "platform_audit_events" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "platform_audit_events" FORCE ROW LEVEL SECURITY;
GRANT SELECT, INSERT ON "platform_audit_events" TO kenisha_platform;
CREATE POLICY "platform_audit_events_platform_all" ON "platform_audit_events" TO kenisha_platform
  USING (true) WITH CHECK (true);

-- support_access_requests ----------------------------------------------------------
ALTER TABLE "support_access_requests" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "support_access_requests" FORCE ROW LEVEL SECURITY;

-- Platform: read all requests, create new ones in REQUESTED state only. No UPDATE, so a
-- Super Admin can never approve their own request.
GRANT SELECT, INSERT ON "support_access_requests" TO kenisha_platform;
CREATE POLICY "support_access_platform_read" ON "support_access_requests" FOR SELECT
  TO kenisha_platform USING (true);
CREATE POLICY "support_access_platform_request" ON "support_access_requests" FOR INSERT
  TO kenisha_platform WITH CHECK ("status" = 'REQUESTED');

-- Hospital: read and decide its own requests only.
GRANT SELECT ON "support_access_requests" TO kenisha_app;
GRANT UPDATE ("status", "decided_by_user_id", "decided_at", "approved_until", "updated_at")
  ON "support_access_requests" TO kenisha_app;
CREATE POLICY "support_access_tenant_isolation" ON "support_access_requests" TO kenisha_app
  USING ("tenant_id" = (SELECT "current_tenant_id"()))
  WITH CHECK ("tenant_id" = (SELECT "current_tenant_id"()));

COMMIT;
